-- Pipeline: troca do histórico 2025 + carga do histórico 2024 (Asana 1220616205316603 — "Pipeline 2025 e 2024", pedido do Daniel)
-- Rodar no Supabase (projeto jibstoejwfvpzlhymoxe) ANTES ou logo depois do merge. Idempotente (pode rodar de novo: apaga e recarga 2024/2025).
--
-- Fontes (lidas em 2026-11-17, export CSV da aba inteira, sem filtro):
--   2025: "Prospecção Snack 2025 - GLOBAL", aba "Input"        https://docs.google.com/spreadsheets/d/1_jfdMhk8ql2yLEQaiwiS3NcSc9Yi3g2JhzSmTItqxQA/edit
--   2024: "Prospecção Snack 2024", aba "Input BR 2024"          https://docs.google.com/spreadsheets/d/1qmEl-GvT_JnHB2hK2AbThamxTvPq6YLd3KuoZj2-_s4/edit
--
-- Template oficial = base 2026 (aba "Pipeline" da NEW - PIPELINE COMERCIAL 2026). Mapeamento:
--   ETAPA -> estagio ("10/11/12 GANHO" = erro de digitação, vira "09 GANHO")
--   EMPRESA/MARCA -> empresa · NOME DO PROJETO -> projeto
--   UNIT (2025; senão UNIDADE) -> unidade (vazio = Brasil)
--   SERVIÇO -> servico: Fee/Upsell iguais; AON (always on) -> Fee; demais (Outras Linhas, Campanha, Influencers, Live Shopping, UGC Creators) -> Projeto
--   DATA FECHAMENTO (nome do mês) -> mes_fechamento · TEMPERATURA -> temperatura (negociação sem temperatura = 3.COLD)
--   BUDGET -> budget · % ANO SEGUINTE -> pct_ano_seguinte
--   MOTIVO PERDA -> motivo_perda só se for um dos motivos do template 2026 (senão NULL)
--   gerado_por é coluna gerada (Upsell = Atendimento, resto = New Business); concorrencia = false (não existe nas bases antigas)
-- Desconsiderados (não existem no template 2026): CONTATO - EMAIL, CLIENTE / PROSPECT, NEW BUSINESS (nome da pessoa), ORIGEM,
--   RESPONSÁVEL, DATAS (briefing/apresentação/início/fim), BUDGET ANO ATUAL/PROJETADO/PRÓXIMO ANO (calculados pelo app), OBS,
--   CARTA ORÇAMENTO, campos HubSpot, proprietário, domínio, setor, tipo de proposta/campanha, contato (nome/e-mail/telefone), cargo, status.
--
-- origem = 'historico' (não 'sheet'): a sincronização automática da planilha 2026 só apaga linhas origem='sheet', então
-- o histórico importado não é apagado por ela. E a config da planilha deixa de puxar a aba antiga "0Dados2025" (aba_hist),
-- senão o resumo antigo (só ETAPA/SERVICO/BUDGET, empresa "Histórico 2025") voltaria a ser gravado por cima.
--
-- Resumo esperado: {"2025": {"linhas": 500, "por_estagio": {"07 PROPOSTA ENVIADA": 71, "09 GANHO": 190, "08 DECLINADOS/PERDIDOS": 239}, "budget": 143191676.0, "por_unidade": {"USA": 26, "Portugal": 25, "Italia": 12, "Brasil": 437}, "por_servico": {"Fee": 111, "Projeto": 218, "Upsell": 171}}, "2024": {"linhas": 417, "por_estagio": {"07 PROPOSTA ENVIADA": 64, "08 DECLINADOS/PERDIDOS": 187, "09 GANHO": 166}, "budget": 136670598.0, "por_unidade": {"Italia": 3, "Portugal": 12, "Brasil": 394, "USA": 8}, "por_servico": {"Fee": 176, "Projeto": 241}}}

BEGIN;

-- 1) Apaga o histórico 2025 atual (resumo "Histórico 2025" vindo da aba 0Dados2025) e qualquer carga anterior desta migração
DELETE FROM public.pipeline_deals
 WHERE ano IN (2024, 2025)
   AND origem IN ('sheet', 'historico');

-- 2) Para de sincronizar a aba de histórico antiga (mantém o resto da config da planilha 2026)
UPDATE public.pipeline_config
   SET valor = valor - 'aba_hist' - 'gid_hist' - 'ano_hist' - 'hist', updated_at = now()
 WHERE chave = 'sheet';

-- 3) Histórico 2025 (500 linhas)

-- 4) Histórico 2024 (417 linhas)

COMMIT;

